scwin.trs_Save_onfail = async function () {
    try {
        await $c.fil.alertJobResult('F');
        $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07171.trs_Save_onfail" });
    }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description btn_Acpt 을(를) 값을 넣는다 · btn_Reject 을(를) 값을 넣는다 외
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_onsuccess = async function () {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
        scwin.btn_Acpt.setDisabled(true);
        scwin.btn_Acpt.setDisabled(true);
        $c.util.getComponent('btn_Reject').setSrc("../img/btn_reject_d.gif");
        $c.util.getComponent('btn_Reject').setDisabled(true);
        await $c.fil.alertJobResult('S1');
        scwin.parentRefresh();
        $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07171.trs_Save_onsuccess" });
    }
};

