/**
 * @method
 * @name btn_Acpt_onclick
 * @description btn_Acpt 의 onclick 에서 알림을 띄운다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Acpt_onclick = async function () {
    try {
        const msg = "(※ 주의) 해당 자료를 접수하기 전 \n\n" + " '상장예비심사신청현황(STF07100)' 화면 등에서 상장예비심사 \n" + "승인절차 등록 여부를 확인하시기 바랍니다.";
        await $c.win.alert(msg);
        const vAnswer = await $c.win.confirm('접수처리 하시겠습니까?');
        if (vAnswer === true) {
            await scwin.sbm_trs_Save("33");
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07171.btn_Acpt_onclick' }); }
};

