scwin.syncFnc = async function () {
    let url = "/lstinvstg/PubFnc.do?SCREN_ID=" + "ULDSTF07171.gfm" + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_01 + "&method=readFncDtl";
